// =============================================================================
// Cluster Visualization Artifact
// =============================================================================

interface ClusterContent {
  n_clusters: number;
  populations: number[];
  representatives: number[];
  tsne_coordinates?: Array<[number, number]>;
}

interface ClusterVisualizationProps {
  content: ClusterContent;
}

export const ClusterVisualizationArtifact: React.FC<ClusterVisualizationProps> = ({ content }) => {
  const { n_clusters, populations, representatives } = content;
  const totalPopulation = populations.reduce((a, b) => a + b, 0);
  const maxPopulation = Math.max(...populations);

  return (
    <div className="bg-slate-900 rounded-xl p-4 border border-slate-800">
      {/* Header */}
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-sm font-semibold text-slate-200 flex items-center gap-2">
          <svg className="w-4 h-4 text-orange-400" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <circle cx="12" cy="12" r="3" />
            <circle cx="19" cy="12" r="2" />
            <circle cx="5" cy="12" r="2" />
            <circle cx="12" cy="5" r="2" />
            <circle cx="12" cy="19" r="2" />
          </svg>
          Conformational Clusters
        </h3>
        <span className="text-xs text-slate-500">{n_clusters} clusters</span>
      </div>

      {/* Summary */}
      <div className="grid grid-cols-2 gap-3 mb-4">
        <div className="bg-slate-800/50 rounded-lg p-3">
          <div className="text-lg font-bold text-orange-400">{totalPopulation}</div>
          <div className="text-[10px] text-slate-500 uppercase">Conformations</div>
        </div>
        <div className="bg-slate-800/50 rounded-lg p-3">
          <div className="text-lg font-bold text-slate-300">{n_clusters}</div>
          <div className="text-[10px] text-slate-500 uppercase">Representatives</div>
        </div>
      </div>

      {/* Population Distribution */}
      <div className="space-y-1.5">
        <div className="text-xs text-slate-500 mb-2">Cluster Populations</div>
        {populations.slice(0, 10).map((pop, idx) => {
          const width = (pop / maxPopulation) * 100;
          const percentage = ((pop / totalPopulation) * 100).toFixed(1);

          return (
            <div key={idx} className="flex items-center gap-2">
              <span className="text-[10px] text-slate-500 w-8">C{idx + 1}</span>
              <div className="flex-1 h-3 bg-slate-800 rounded overflow-hidden">
                <div
                  className="h-full bg-gradient-to-r from-orange-500 to-amber-400 transition-all duration-300"
                  style={{ width: `${width}%` }}
                />
              </div>
              <span className="text-xs text-slate-400 w-12 text-right">{percentage}%</span>
            </div>
          );
        })}
        {populations.length > 10 && (
          <div className="text-xs text-slate-600 text-center mt-2">
            +{populations.length - 10} more clusters
          </div>
        )}
      </div>

      {/* Representative Frames */}
      <div className="mt-4 pt-3 border-t border-slate-800">
        <div className="text-xs text-slate-500 mb-2">Representative Frames</div>
        <div className="flex flex-wrap gap-1">
          {representatives.slice(0, 20).map((frame, idx) => (
            <span
              key={idx}
              className="px-2 py-0.5 bg-orange-900/30 rounded text-xs text-orange-300 font-mono"
            >
              {frame}
            </span>
          ))}
        </div>
      </div>
    </div>
  );
};

