// =============================================================================
// Artifact Feedback Component (Google Docs-style)
// =============================================================================

const API_BASE = 'http://localhost:8002';

interface FeedbackItem {
  id: string;
  user_id: string;
  comment: string;
  resolved: boolean;
  created_at: string;
}

interface ArtifactWithFeedbackProps {
  artifact: Artifact;
  onStructureClick?: (pdbData: string) => void;
  children: React.ReactNode;
}

const ArtifactWithFeedback: React.FC<ArtifactWithFeedbackProps> = ({
  artifact,
  children
}) => {
  const [showComments, setShowComments] = useState(false);
  const [comments, setComments] = useState<FeedbackItem[]>([]);
  const [newComment, setNewComment] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Fetch existing comments
  useEffect(() => {
    const fetchComments = async () => {
      try {
        const response = await fetch(`${API_BASE}/feedback/${artifact.id}`);
        if (response.ok) {
          const data = await response.json();
          setComments(data.feedback || []);
        }
      } catch (e) {
        console.log('Failed to fetch comments:', e);
      }
    };
    if (showComments) {
      fetchComments();
    }
  }, [artifact.id, showComments]);

  const handleAddComment = async () => {
    if (!newComment.trim() || isSubmitting) return;

    setIsSubmitting(true);
    try {
      const response = await fetch(`${API_BASE}/feedback`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          artifact_id: artifact.id,
          comment: newComment.trim()
        })
      });

      if (response.ok) {
        const newFeedback = await response.json();
        setComments(prev => [...prev, newFeedback]);
        setNewComment('');
      }
    } catch (e) {
      console.error('Failed to add comment:', e);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleResolve = async (feedbackId: string) => {
    try {
      const response = await fetch(`${API_BASE}/feedback/${feedbackId}/resolve`, {
        method: 'PUT'
      });
      if (response.ok) {
        setComments(prev =>
          prev.map(c => c.id === feedbackId ? { ...c, resolved: true } : c)
        );
      }
    } catch (e) {
      console.error('Failed to resolve comment:', e);
    }
  };

  const unresolvedCount = comments.filter(c => !c.resolved).length;

  return (
    <div className="relative">
      {children}

      {/* Comment Button */}
      <div className="absolute top-2 right-2 flex items-center gap-2">
        <button
          onClick={() => setShowComments(!showComments)}
          className={`flex items-center gap-1.5 px-2 py-1 text-xs rounded-lg transition-colors ${
            showComments
              ? 'bg-am-accent text-white'
              : 'bg-am-tertiary text-am-text-secondary hover:bg-am-border'
          }`}
        >
          <MessageCircle className="w-3 h-3" />
          <span>Comments</span>
          {unresolvedCount > 0 && (
            <span className="bg-red-500 text-white text-[10px] px-1.5 rounded-full">
              {unresolvedCount}
            </span>
          )}
        </button>
      </div>

      {/* Comments Panel */}
      {showComments && (
        <div className="mt-3 pt-3 border-t border-am-border space-y-3">
          {/* Existing Comments */}
          {comments.length > 0 && (
            <div className="space-y-2">
              {comments.map(comment => (
                <div
                  key={comment.id}
                  className={`p-2 rounded-lg text-xs ${
                    comment.resolved
                      ? 'bg-am-tertiary/50 opacity-60'
                      : 'bg-am-tertiary'
                  }`}
                >
                  <div className="flex items-start justify-between gap-2">
                    <div className="flex-1 min-w-0">
                      <div className="font-medium text-am-text-primary mb-1">
                        {comment.user_id}
                      </div>
                      <div className="text-am-text-secondary whitespace-pre-wrap">
                        {comment.comment}
                      </div>
                      <div className="text-am-text-muted mt-1 text-[10px]">
                        {new Date(comment.created_at).toLocaleString()}
                      </div>
                    </div>
                    {!comment.resolved && (
                      <button
                        onClick={() => handleResolve(comment.id)}
                        className="flex-shrink-0 p-1 text-green-400 hover:bg-green-500/20 rounded transition-colors"
                        title="Mark as resolved"
                      >
                        <Check className="w-3 h-3" />
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* New Comment Input */}
          <div className="flex gap-2">
            <input
              type="text"
              value={newComment}
              onChange={(e) => setNewComment(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleAddComment()}
              placeholder="Add a comment..."
              className="flex-1 px-3 py-2 text-xs bg-am-secondary border border-am-border rounded-lg text-am-text-primary placeholder-am-text-muted focus:outline-none focus:border-am-accent"
            />
            <button
              onClick={handleAddComment}
              disabled={!newComment.trim() || isSubmitting}
              className="px-3 py-2 bg-am-accent text-white text-xs rounded-lg hover:bg-am-accent-hover disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              <Send className="w-3 h-3" />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

// =============================================================================
// Main Artifact Renderer
// =============================================================================

interface ArtifactRendererProps {
  artifact: Artifact;
  onStructureClick?: (pdbData: string) => void;
  enableFeedback?: boolean;
}

export const ArtifactRenderer: React.FC<ArtifactRendererProps> = ({
  artifact,
  onStructureClick,
  enableFeedback = true,
}) => {
  const renderArtifact = () => {
    switch (artifact.type) {
      case ArtifactType.TASK_LIST:
        return <TaskListArtifact content={artifact.content as TaskListContent} />;

      case ArtifactType.DOCKING_RESULT:
        return <DockingResultArtifact content={artifact.content as DockingResultContent} />;

      case ArtifactType.INTERACTION_MAP:
        return <InteractionMapArtifact content={artifact.content as InteractionMapContent} />;

      case ArtifactType.LITERATURE_RESULT:
        return <LiteratureArtifact content={artifact.content as LiteratureContent} />;

      case ArtifactType.CLUSTER_VISUALIZATION:
        return <ClusterVisualizationArtifact content={artifact.content as ClusterContent} />;

      case ArtifactType.IMPLEMENTATION_PLAN:
        return <MarkdownArtifact content={artifact.content as string} title="Implementation Plan" />;

      case ArtifactType.WALKTHROUGH:
        return <MarkdownArtifact content={artifact.content as string} title="Walkthrough" />;

      case ArtifactType.STRUCTURE_3D:
        return (
          <div className="bg-slate-900 rounded-xl p-4 border border-slate-800">
            <div className="flex items-center justify-between mb-3">
              <h3 className="text-sm font-semibold text-slate-200 flex items-center gap-2">
                <svg className="w-4 h-4 text-green-400" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M12 2L2 7l10 5 10-5-10-5z" />
                  <path d="M2 17l10 5 10-5" />
                  <path d="M2 12l10 5 10-5" />
                </svg>
                3D Structure
              </h3>
              {onStructureClick && (
                <button
                  onClick={() => onStructureClick(artifact.content.pdb_data)}
                  className="text-xs px-3 py-1 bg-green-500 hover:bg-green-600 text-white rounded transition-colors"
                >
                  View in 3D
                </button>
              )}
            </div>
            <div className="grid grid-cols-2 gap-2 text-xs">
              {artifact.content.metadata?.ped_id && (
                <div className="bg-slate-800/50 rounded p-2">
                  <span className="text-slate-500">PED ID:</span>
                  <span className="ml-2 text-slate-300 font-mono">{artifact.content.metadata.ped_id}</span>
                </div>
              )}
              {artifact.content.metadata?.n_conformations && (
                <div className="bg-slate-800/50 rounded p-2">
                  <span className="text-slate-500">Conformations:</span>
                  <span className="ml-2 text-slate-300">{artifact.content.metadata.n_conformations}</span>
                </div>
              )}
            </div>
          </div>
        );

      default:
        return (
          <div className="bg-slate-900 rounded-xl p-4 border border-slate-800">
            <pre className="text-xs text-slate-400 overflow-auto">
              {JSON.stringify(artifact.content, null, 2)}
            </pre>
          </div>
        );
    }
  };

  // Wrap with feedback if enabled
  if (enableFeedback) {
    return (
      <ArtifactWithFeedback artifact={artifact} onStructureClick={onStructureClick}>
        {renderArtifact()}
      </ArtifactWithFeedback>
    );
  }

  return renderArtifact();
};

export default ArtifactRenderer;
